import java.util.*;

public class Main {
    public static void main(String[] args) {
        System.out.println("user: what is 2+3?");
        // Stand-in for the model: it returns structured calls, it executes nothing.
        String[][] proposed = {{"c1", "add", "2", "3"}, {"c2", "mul", "2", "3"}};
        Map<String, String> results = new LinkedHashMap<>();
        for (String[] c : proposed) {
            int a = Integer.parseInt(c[2]);
            int b = Integer.parseInt(c[3]);
            System.out.println("model -> tool_use " + c[0] + " " + c[1] + "(" + a + ", " + b + ")");
            String r;
            if (c[1].equals("add")) {
                r = String.valueOf(a + b);              // the real function
            } else {
                r = "error: unknown tool " + c[1];      // the app validates first
            }
            results.put(c[0], r);   // each result is tied to the call id
            System.out.println("app   -> tool_result " + c[0] + " " + r);
        }
        System.out.println("model -> final: 2 + 3 = " + results.get("c1"));
    }
}

