public class Main {
    static Map<String, String> docs = new HashMap<>();

    static String search(String q) {            // the tool: returns an observation
        return docs.getOrDefault(q, "no result");
    }

    static void run(int budget) {
        System.out.println("== budget " + budget + " ==");
        String[] queries = {"pricing", "faq", "price list"};   // scripted model actions
        for (int step = 0; step < budget; step++) {            // the step cap lives in code
            String obs = search(queries[step]);
            System.out.println("step " + (step + 1) + ": search(" + queries[step] + ") -> " + obs);
            if (obs.contains("42")) {                          // the model sees the answer
                System.out.println("finish: " + obs);
                return;
            }
        }
        System.out.println("stopped: budget of " + budget + " steps used");
    }

    public static void main(String[] args) {
        docs.put("faq", "see price list");
        docs.put("price list", "plan costs 42 dollars");
        run(5);
        run(2);
    }
}

