import java.util.*;

public class Main {
    static String key(String q) {
        // lower-case, drop filler words, sort: "the Pricing" and "pricing" match
        List<String> words = new ArrayList<>();
        for (String w : q.toLowerCase().split("\\s+")) {
            if (!w.equals("the") && !w.equals("a")) words.add(w);
        }
        Collections.sort(words);
        return String.join(" ", words);
    }

    public static void main(String[] args) {
        String[] queries = {"pricing", "Pricing plans", "pricing", "the pricing", "pricing plans", "other"};
        Map<String, Integer> seen = new HashMap<>();
        for (int i = 1; i <= queries.length; i++) {
            String q = queries[i - 1];
            String k = key(q);
            seen.merge(k, 1, Integer::sum);       // O(words) work per call
            System.out.println("call " + i + " '" + q + "' key=" + k + " seen=" + seen.get(k));
            if (seen.get(k) >= 3) {               // hard limit on repeats
                System.out.println("guard: stopping, near-duplicate call repeated 3 times");
                break;
            }
        }
    }
}

