#include <bits/stdc++.h>
using namespace std;

string key(string q) {
    // lower-case, drop filler words, sort: "the Pricing" and "pricing" match
    for (auto& ch : q) ch = tolower(ch);
    stringstream ss(q);
    vector<string> words;
    string w;
    while (ss >> w) if (w != "the" && w != "a") words.push_back(w);
    sort(words.begin(), words.end());
    string out;
    for (size_t i = 0; i < words.size(); i++) out += (i ? " " : "") + words[i];
    return out;
}

int main() {
    vector<string> queries = {"pricing", "Pricing plans", "pricing", "the pricing", "pricing plans", "other"};
    map<string, int> seen;
    for (int i = 1; i <= (int)queries.size(); i++) {
        string k = key(queries[i - 1]);
        seen[k]++;                                // O(words) work per call
        cout << "call " << i << " '" << queries[i - 1] << "' key=" << k
             << " seen=" << seen[k] << "\n";
        if (seen[k] >= 3) {                       // hard limit on repeats
            cout << "guard: stopping, near-duplicate call repeated 3 times\n";
            break;
        }
    }
}

