using System.Collections.Generic;

class Program
{
    static string Key(string q)
    {
        // lower-case, drop filler words, sort: "the Pricing" and "pricing" match
        var words = new List<string>();
        foreach (var w in q.ToLower().Split(' '))
            if (w != "the" && w != "a") words.Add(w);
        words.Sort(string.CompareOrdinal);
        return string.Join(" ", words.ToArray());
    }

    static void Main()
    {
        string[] queries = {"pricing", "Pricing plans", "pricing", "the pricing", "pricing plans", "other"};
        var seen = new Dictionary<string, int>();
        for (int i = 1; i <= queries.Length; i++)
        {
            string k = Key(queries[i - 1]);
            int n;
            seen.TryGetValue(k, out n);
            seen[k] = n + 1;                      // O(words) work per call
            Console.WriteLine("call " + i + " '" + queries[i - 1] + "' key=" + k + " seen=" + seen[k]);
            if (seen[k] >= 3)                     // hard limit on repeats
            {
                Console.WriteLine("guard: stopping, near-duplicate call repeated 3 times");
                break;
            }
        }
    }
}
